CREATE DATABASE IF NOT EXISTS erp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE erp;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS activity_logs,audit_logs,notifications,payroll_items,payroll,leave_requests,leave_types,attendance,journal_entry_items,journal_entries,accounts,expense_categories,expenses,payments,invoice_items,invoices,sales_quotation_items,sales_quotations,sales_order_items,sales_orders,goods_receipt_items,goods_receipts,purchase_order_items,purchase_orders,stock_transfers,stock_adjustments,stock_movements,stock,warehouse_locations,warehouses,tax_rates,product_variants,products,units,categories,supplier_contacts,suppliers,customer_contacts,customers,employee_documents,employees,departments,branches,companies,password_resets,sessions,user_roles,role_permissions,permissions,roles,users,settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive','suspended') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,index idx_users_status(status),index idx_users_deleted(deleted_at));
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255) NULL);
CREATE TABLE role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE user_roles(user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE sessions(id VARCHAR(128) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,ip_address VARCHAR(45),user_agent VARCHAR(512),payload TEXT,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,index idx_sessions_exp(expires_at));
CREATE TABLE password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,registration_no VARCHAR(100),email VARCHAR(190),phone VARCHAR(50),address TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE branches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,address TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE departments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE employees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_no VARCHAR(50) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NULL,department_id BIGINT UNSIGNED NULL,position VARCHAR(120),first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100),email VARCHAR(190),phone VARCHAR(50),joining_date DATE,employment_status ENUM('active','inactive','terminated') DEFAULT 'active',basic_salary DECIMAL(15,2) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,index idx_emp_deleted(deleted_at));
CREATE TABLE employee_documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,file_name VARCHAR(255) NOT NULL,file_path VARCHAR(500) NOT NULL,mime_type VARCHAR(100),file_size BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE customers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) UNIQUE,name VARCHAR(190) NOT NULL,email VARCHAR(190),phone VARCHAR(50),address TEXT,credit_limit DECIMAL(15,2) DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,index idx_customer_name(name));
CREATE TABLE customer_contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190),phone VARCHAR(50),position VARCHAR(120),FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) UNIQUE,name VARCHAR(190) NOT NULL,email VARCHAR(190),phone VARCHAR(50),address TEXT,payment_terms VARCHAR(120),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL);
CREATE TABLE supplier_contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,supplier_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190),phone VARCHAR(50),position VARCHAR(120),FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE);
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL UNIQUE,description TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE units(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,symbol VARCHAR(20) NOT NULL UNIQUE);
CREATE TABLE tax_rates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,rate DECIMAL(8,4) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,category_id BIGINT UNSIGNED NULL,unit_id BIGINT UNSIGNED NULL,tax_rate_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,description TEXT,cost_price DECIMAL(15,2) NOT NULL DEFAULT 0,selling_price DECIMAL(15,2) NOT NULL DEFAULT 0,reorder_level DECIMAL(15,3) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE SET NULL,FOREIGN KEY(tax_rate_id) REFERENCES tax_rates(id) ON DELETE SET NULL,index idx_product_name(name));
CREATE TABLE product_variants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,attributes JSON NULL,price DECIMAL(15,2) NULL,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE warehouses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL UNIQUE,address TEXT,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE warehouse_locations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,warehouse_id BIGINT UNSIGNED NOT NULL,code VARCHAR(80) NOT NULL,description VARCHAR(255),UNIQUE(warehouse_id,code),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE);
CREATE TABLE stock(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL DEFAULT 0,average_cost DECIMAL(15,2) NOT NULL DEFAULT 0,UNIQUE(product_id,warehouse_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,type ENUM('receipt','sale','adjustment','transfer_in','transfer_out','return') NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_cost DECIMAL(15,2) DEFAULT 0,reference_type VARCHAR(80),reference_id BIGINT UNSIGNED NULL,note VARCHAR(255),created_by BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,index idx_stock_move(product_id,warehouse_id,created_at));
CREATE TABLE stock_adjustments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,warehouse_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(255),status ENUM('draft','approved','cancelled') DEFAULT 'draft',created_by BIGINT UNSIGNED,approved_by BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(approved_by) REFERENCES users(id));
CREATE TABLE stock_transfers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_warehouse_id BIGINT UNSIGNED NOT NULL,destination_warehouse_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','approved','completed','cancelled') DEFAULT 'draft',created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(destination_warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE purchase_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_no VARCHAR(50) UNIQUE NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','pending','approved','processing','completed','cancelled') DEFAULT 'draft',order_date DATE NOT NULL,total DECIMAL(15,2) DEFAULT 0,created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE purchase_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_price DECIMAL(15,2) NOT NULL,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) NOT NULL,FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE goods_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,grn_no VARCHAR(50) UNIQUE NOT NULL,purchase_order_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','received','cancelled') DEFAULT 'draft',received_at DATETIME NULL,created_by BIGINT UNSIGNED,FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE goods_receipt_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,goods_receipt_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_cost DECIMAL(15,2) NOT NULL,FOREIGN KEY(goods_receipt_id) REFERENCES goods_receipts(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE sales_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(50) UNIQUE NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','pending','approved','processing','completed','cancelled') DEFAULT 'draft',order_date DATE NOT NULL,subtotal DECIMAL(15,2) DEFAULT 0,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) DEFAULT 0,created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE sales_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sales_order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_price DECIMAL(15,2) NOT NULL,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) NOT NULL,FOREIGN KEY(sales_order_id) REFERENCES sales_orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE sales_quotations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_no VARCHAR(50) UNIQUE NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,status ENUM('draft','sent','accepted','rejected','expired') DEFAULT 'draft',quotation_date DATE NOT NULL,valid_until DATE NULL,total DECIMAL(15,2) DEFAULT 0,created_by BIGINT UNSIGNED,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE sales_quotation_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_price DECIMAL(15,2) NOT NULL,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) NOT NULL,FOREIGN KEY(quotation_id) REFERENCES sales_quotations(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_no VARCHAR(50) UNIQUE NOT NULL,customer_id BIGINT UNSIGNED NULL,sales_order_id BIGINT UNSIGNED NULL,status ENUM('draft','issued','partially_paid','paid','overdue','cancelled') DEFAULT 'draft',issue_date DATE NOT NULL,due_date DATE NULL,subtotal DECIMAL(15,2) DEFAULT 0,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) DEFAULT 0,balance_due DECIMAL(15,2) DEFAULT 0,created_by BIGINT UNSIGNED,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(sales_order_id) REFERENCES sales_orders(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(15,3) NOT NULL,unit_price DECIMAL(15,2) NOT NULL,discount DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,total DECIMAL(15,2) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference_no VARCHAR(80) UNIQUE NOT NULL,invoice_id BIGINT UNSIGNED NULL,customer_id BIGINT UNSIGNED NULL,amount DECIMAL(15,2) NOT NULL,payment_date DATE NOT NULL,method VARCHAR(50) NOT NULL,note VARCHAR(255),created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE SET NULL,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE expense_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_no VARCHAR(50) UNIQUE NOT NULL,category_id BIGINT UNSIGNED NULL,amount DECIMAL(15,2) NOT NULL,expense_date DATE NOT NULL,description VARCHAR(255),status ENUM('draft','approved','paid','cancelled') DEFAULT 'draft',created_by BIGINT UNSIGNED,FOREIGN KEY(category_id) REFERENCES expense_categories(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(190) NOT NULL,type ENUM('asset','liability','equity','revenue','expense') NOT NULL,parent_id BIGINT UNSIGNED NULL,active BOOLEAN DEFAULT TRUE,FOREIGN KEY(parent_id) REFERENCES accounts(id) ON DELETE SET NULL);
CREATE TABLE journal_entries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entry_no VARCHAR(50) UNIQUE NOT NULL,entry_date DATE NOT NULL,description VARCHAR(255),status ENUM('draft','posted','cancelled') DEFAULT 'draft',created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE journal_entry_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,journal_entry_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,debit DECIMAL(15,2) DEFAULT 0,credit DECIMAL(15,2) DEFAULT 0,description VARCHAR(255),FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,check_in DATETIME NULL,check_out DATETIME NULL,status ENUM('present','absent','late','half_day','leave') DEFAULT 'present',UNIQUE(employee_id,attendance_date),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE leave_types(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,annual_days DECIMAL(8,2) NOT NULL DEFAULT 0);
CREATE TABLE leave_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,leave_type_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,days DECIMAL(8,2) NOT NULL,reason TEXT,status ENUM('pending','approved','rejected','cancelled') DEFAULT 'pending',approved_by BIGINT UNSIGNED NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id),FOREIGN KEY(leave_type_id) REFERENCES leave_types(id),FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE payroll(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id BIGINT UNSIGNED NOT NULL,pay_period CHAR(7) NOT NULL,basic_salary DECIMAL(15,2) NOT NULL,allowances DECIMAL(15,2) DEFAULT 0,overtime DECIMAL(15,2) DEFAULT 0,deductions DECIMAL(15,2) DEFAULT 0,tax DECIMAL(15,2) DEFAULT 0,gross_salary DECIMAL(15,2) NOT NULL,net_salary DECIMAL(15,2) NOT NULL,status ENUM('draft','approved','paid') DEFAULT 'draft',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(employee_id,pay_period),FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE payroll_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payroll_id BIGINT UNSIGNED NOT NULL,type ENUM('allowance','overtime','deduction','tax') NOT NULL,name VARCHAR(120) NOT NULL,amount DECIMAL(15,2) NOT NULL,FOREIGN KEY(payroll_id) REFERENCES payroll(id) ON DELETE CASCADE);
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,message TEXT NOT NULL,type VARCHAR(50),read_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,index idx_notif_user(user_id,read_at));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,module VARCHAR(80) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED NULL,old_values JSON NULL,new_values JSON NULL,ip_address VARCHAR(45),user_agent VARCHAR(512),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,index idx_audit_module(module,created_at),index idx_audit_entity(entity_type,entity_id));
CREATE TABLE activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,activity VARCHAR(255) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(190) UNIQUE NOT NULL,setting_value TEXT NULL,is_secret BOOLEAN DEFAULT FALSE,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
